_code = re.sub(r"#.*", "", student_code)
_lp = re.escape(lp)
probleme = None
if "..." in _code:
    probleme = "Il reste des `...` : remplacez-les par du code."
elif re.search(r"\b(count|index)\b", _code):
    probleme = "`count` et `index` sont interdits : c'est la boucle qui doit faire le travail."
elif style == "while":
    if re.search(r"\bfor\b", _code):
        probleme = "Ici, la boucle s'écrit avec `while` (pas de `for`)."
    elif not re.search(r"\bwhile\b", _code):
        probleme = "Utilisez une boucle `while`."
    else:
        # l'indice du while doit avancer, sinon la boucle ne s'arrête jamais
        m = re.search(r"\bwhile\s+(\w+)\s*<", _code)
        if m and not re.search(r"\b" + m.group(1) + r"\s*(\+=\s*1\b|=\s*" + m.group(1) + r"\s*\+\s*1\b)", _code):
            probleme = (f"La boucle ne s'arrête jamais : l'indice `{m.group(1)}` n'avance pas. Ajoutez "
                        f"`{m.group(1)} = {m.group(1)} + 1` à la fin du corps de la boucle (au même niveau que le `if`).")
elif style == "libre":
    if re.search(r"\bwhile\b", _code):
        probleme = "Ici, la boucle s'écrit avec `for` (sur les éléments ou sur les indices), pas avec `while`."
    elif not re.search(r"\bfor\b", _code):
        probleme = "Utilisez une boucle `for`."
elif style == "indices":
    if re.search(r"\bwhile\b", _code):
        probleme = "Ici, la boucle s'écrit avec `for` sur les indices (pas de `while`)."
    elif not re.search(r"\bfor\s+\w+\s+in\s+range\s*\(\s*len\s*\(\s*" + _lp + r"\s*\)\s*\)", _code):
        probleme = f"Parcourez les indices avec `for i in range(len({lp})):`."
else:
    if re.search(r"\bwhile\b", _code) or re.search(r"\brange\s*\(", _code) or re.search(r"\b" + _lp + r"\s*\[", _code):
        probleme = f"Ici, on parcourt directement les éléments : `for {var} in {lp}:` (sans `while`, sans `range`, sans `{lp}[...]`)."
    elif not re.search(r"\bfor\s+\w+\s+in\s+" + _lp + r"\s*:", _code):
        probleme = f"Parcourez la liste avec `for {var} in {lp}:`."
if probleme is None and len(re.findall(r"\bin\b", _code)) > len(re.findall(r"\bfor\b", _code)):
    probleme = "N'utilisez pas l'opérateur `in` pour tester la présence : c'est la boucle qui doit examiner les éléments."
fn = student.get(fname)
if probleme:
    check(False, probleme)
elif not callable(fn):
    check(False, f"la fonction `{fname}` doit être définie")
else:
    for args, attendu in cases:
        texte_appel = fname + "(" + ", ".join(repr(a) for a in args) + ")"
        try:
            obtenu = fn(*copy.deepcopy(args))
        except Exception as e:
            if type(e).__name__ == "TimeLimit":
                raise
            check(False, f"`{texte_appel}` provoque une erreur : {erreur(e)}")
            continue
        check_equal(obtenu, attendu, f"`{texte_appel}` renvoie `{obtenu!r}` au lieu de `{attendu!r}`")

